// This code has been partially generated by an AI.
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { processAllFiles } from '../src/processor';
import type { LlmsTxtOptions } from '../src/types';

// Mock fs
vi.mock('node:fs', () => ({
  default: {
    readFileSync: vi.fn(),
    mkdirSync: vi.fn(),
    existsSync: vi.fn(),
    writeFileSync: vi.fn(),
  },
}));

// Mock aiProvider
vi.mock('../src/aiProvider', () => ({
  generateAISummary: vi.fn().mockResolvedValue('AI Summary Result'),
}));

describe('processor', () => {
  const logger = {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
  };

  const options: LlmsTxtOptions = {
    site: 'https://example.com',
    aiProvider: 'ollama',
    concurrency: 2,
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('processes files and returns valid page info', async () => {
    const htmlFiles = ['/dist/index.html', '/dist/blog/post.html'];
    const resolvedDistPath = '/dist';

    (fs.readFileSync as any).mockReturnValue(
      '<html><title>Test</title><body><p>Content</p></body></html>'
    );

    const result = await processAllFiles(htmlFiles, resolvedDistPath, options, logger, '/cache');

    expect(result).toHaveLength(2);
    expect(result[0].url).toBe('https://example.com/');
    expect(result[1].url).toBe('https://example.com/blog/post');
    expect(result[0].summary).toBe('AI Summary Result');
    expect(logger.error).not.toHaveBeenCalled();
  });

  it('filters out pages with empty summaries', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    (generateAISummary as any).mockResolvedValueOnce(''); // First one fails/is empty
    (generateAISummary as any).mockResolvedValueOnce('Valid');

    const htmlFiles = ['/dist/fail.html', '/dist/success.html'];
    (fs.readFileSync as any).mockReturnValue('<html><body><p>Text</p></body></html>');

    const result = await processAllFiles(htmlFiles, '/dist', options, logger, '/cache');

    expect(result).toHaveLength(1);
    expect(result[0].summary).toBe('Valid');
  });

  it('handles read errors gracefully', async () => {
    (fs.readFileSync as any).mockImplementation(() => {
      throw new Error('Read error');
    });

    const result = await processAllFiles(['/dist/error.html'], '/dist', options, logger, '/cache');

    expect(result).toHaveLength(0);
    expect(logger.error).toHaveBeenCalledWith(expect.stringContaining('Failed to process'));
  });

  it('uses environment variables as fallback for API keys', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    const htmlFiles = ['/dist/test.html'];
    (fs.readFileSync as any).mockReturnValue('<html><title>Test</title></html>');

    // Test Gemini
    process.env.GEMINI_API_KEY = 'gemini-env-key';
    await processAllFiles(htmlFiles, '/dist', { aiProvider: 'gemini' }, logger, '/cache');
    expect(generateAISummary).toHaveBeenCalledWith(
      expect.objectContaining({ apiKey: 'gemini-env-key' })
    );

    // Test OpenAI
    process.env.OPENAI_API_KEY = 'openai-env-key';
    await processAllFiles(htmlFiles, '/dist', { aiProvider: 'openai' }, logger, '/cache');
    expect(generateAISummary).toHaveBeenCalledWith(
      expect.objectContaining({ apiKey: 'openai-env-key' })
    );

    // Test Claude
    process.env.ANTHROPIC_API_KEY = 'claude-env-key';
    await processAllFiles(htmlFiles, '/dist', { aiProvider: 'claude' }, logger, '/cache');
    expect(generateAISummary).toHaveBeenCalledWith(
      expect.objectContaining({ apiKey: 'claude-env-key' })
    );

    // Cleanup
    delete process.env.GEMINI_API_KEY;
    delete process.env.OPENAI_API_KEY;
    delete process.env.ANTHROPIC_API_KEY;
  });

  it('uses h2/h3 prompt when page has no title or h1', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    (fs.readFileSync as any).mockReturnValue(
      '<html><body><h2>Section</h2><h3>Sub</h3></body></html>'
    );
    await processAllFiles(['/dist/no-title.html'], '/dist', options, logger, '/cache');
    expect(generateAISummary).toHaveBeenCalledWith(
      expect.objectContaining({ prompt: expect.any(String) })
    );
  });

  it('logs error when generateAISummary throws', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    (generateAISummary as any).mockRejectedValueOnce(new Error('AI failure'));
    (fs.readFileSync as any).mockReturnValue('<html><title>Test</title></html>');
    const result = await processAllFiles(['/dist/test.html'], '/dist', options, logger, '/cache');
    expect(logger.error).toHaveBeenCalledWith(expect.stringContaining('AI failure'));
    // Page still returns with empty summary fallback
    expect(result).toHaveLength(0);
  });

  it('normalizes invalid concurrency to a safe minimum', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    (fs.readFileSync as any).mockReturnValue('<html><title>Test</title></html>');
    await expect(
      processAllFiles(['/dist/test.html'], '/dist', { ...options, concurrency: 0 }, logger, '/cache')
    ).resolves.toHaveLength(1);
    expect(generateAISummary).toHaveBeenCalled();
  });

  it('skips excluded paths and handles paragraph-only, empty-body, long input, data-llm, and custom aiHandler', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    const longParagraph = 'word '.repeat(50);
    (fs.readFileSync as any)
      .mockReturnValueOnce(`<html><body><p>${longParagraph}</p><div data-llm='{"k":"v"}'></div></body></html>`)
      .mockReturnValueOnce('<html><head><meta name="description" content="Fallback desc"></head><body></body></html>');

    const customHandler = vi.fn().mockResolvedValue('Custom Summary');
    const result = await processAllFiles(
      ['/dist/excluded.html', 'relative.html', '/dist/empty.html'],
      '/dist',
      {
        exclude: ['/excluded'],
        maxInputLength: 20,
        aiHandler: customHandler,
        geoLinter: false,
      },
      logger,
      '/cache'
    );

    expect(result).toHaveLength(2);
    expect(logger.debug).toHaveBeenCalledWith(expect.stringContaining('Skipping excluded path'));
    expect(generateAISummary).toHaveBeenCalledWith(
      expect.objectContaining({ provider: 'custom', aiHandler: customHandler })
    );
  });

  it('handles non-Error objects thrown by readFileSync or generateAISummary and static mode without AI provider', async () => {
    const { generateAISummary } = await import('../src/aiProvider');
    (generateAISummary as any).mockRejectedValueOnce('string-ai-error');
    (fs.readFileSync as any)
      .mockReturnValueOnce('<html><head><meta name="description" content="Meta summary"></head><body><h1>H1</h1></body></html>')
      .mockReturnValueOnce('<html><head><meta name="description" content="Static desc"></head><body><h1>Static</h1></body></html>')
      .mockImplementationOnce(() => {
        throw 'string-fs-error';
      });

    const resWithAi = await processAllFiles(['/dist/a.html'], '/dist', options, logger, '/cache');
    expect(resWithAi).toHaveLength(1);
    expect(resWithAi[0].summary).toBe('Meta summary');
    expect(logger.error).toHaveBeenCalledWith(expect.stringContaining('string-ai-error'));

    const resStatic = await processAllFiles(
      ['/dist/b.html', '/dist/c.html'],
      '/dist',
      { geoLinter: false },
      logger,
      '/cache'
    );
    expect(resStatic).toHaveLength(1);
    expect(logger.error).toHaveBeenCalledWith(expect.stringContaining('string-fs-error'));
  });
});
